import{_ as i,b as a,a as l,aS as e}from"./chunks/framework.M2Whok06.js";const u=JSON.parse('{"title":"韩国好看的电影","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/韩国movie.md","filePath":"note/movie/韩国movie.md","lastUpdated":1738329418000}'),t={name:"note/movie/韩国movie.md"},o=e('<h1 id="韩国好看的电影" tabindex="-1">韩国好看的电影 <a class="header-anchor" href="#韩国好看的电影" aria-label="Permalink to &quot;韩国好看的电影&quot;">​</a></h1><p>我原本吧，准备只开一篇记录下电影，但是呢，好电影实在是太多了，还是分类一下比较好，特别是韩国的电影，好看的实在是太多了，演技是真的牛逼。 你要说比特效，那肯定是美国电影，但你要说是比亲情，爱情这种题材的，韩国必须第一。不信，你看完我下面推荐的再说信不信。</p><h2 id="七号房的礼物" tabindex="-1">七号房的礼物 <a class="header-anchor" href="#七号房的礼物" aria-label="Permalink to &quot;七号房的礼物&quot;">​</a></h2><ul><li>2013-01-23 韩国 127分钟</li><li>类型：剧情 家庭 喜剧</li><li>导演：李焕庆</li><li>主演：柳承龙 朴信惠 郑镇荣 金正泰 吴达洙</li><li>百科：1997年,只有6岁儿童智商的智障男子李龙久(柳成龙 饰)和可爱的女儿艺胜(葛素媛 饰)相依为命,生活虽然简单清贫,却充满幸福。某天,执着为女儿买美少女战士书包的龙久意外卷入一起幼童诱拐奸杀案,而死者竟是警察局长的女儿。龙久懵懂无知,搞不清状况,昏头昏脑就被投入监狱。在7号牢房中,聚集着走私犯蘇杨浩(吴达洙 饰)、诈骗犯崔春浩(朴元尚 饰)、通奸犯姜万范(金正泰 饰)、恐吓犯老徐(金基灿 饰)和抢劫犯申奉植(郑万植 饰)等五毒俱全的“社会渣滓”。龙久孩子般纯洁的心渐渐感动了这几个“大坏蛋”,他们甚至不惜冒险将艺胜带入牢房与父亲相会。 黑暗冰冷的监牢内,7号牢房阳光满满</li></ul><p>催人泪下的片子</p><p><img src="https://pic.rmb.bdstatic.com/bjh/3ad7bb159bad1e0534916a6f91a421ab.jpeg@h_1280" alt=""></p><h2 id="担保" tabindex="-1">担保 <a class="header-anchor" href="#担保" aria-label="Permalink to &quot;担保&quot;">​</a></h2><ul><li>2020-09-29 韩国 113分钟</li><li>类型：剧情 家庭 喜剧</li><li>导演：康大奎执导，尹济均编剧</li><li>主演：成东镒、河智苑、金熙元、朴昭怡</li><li>百科：该片讲述了两个高利贷业者在讨债时稀里糊涂的被对方将九岁的小女孩作为担保抵押给他们，不得不负责照顾小女孩的故事。</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005F9F62692027EE08C8FFA768" alt=""></p><h2 id="开心家族" tabindex="-1">开心家族 <a class="header-anchor" href="#开心家族" aria-label="Permalink to &quot;开心家族&quot;">​</a></h2><ul><li>2010-12-23 韩国 111分钟</li><li>类型：剧情/喜剧</li><li>导演：金英卓</li><li>主演：车太贤、高昌锡、张英南、李文秀、千宝根</li><li>百科：该片讲述了因寂寞而寻求死亡的尚万遇到了一群大大咧咧的鬼，之后慢慢走向了人生巅峰的故事。</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005D553A28425BD9AFDA15706A" alt=""></p><h2 id="傻瓜" tabindex="-1">傻瓜 <a class="header-anchor" href="#傻瓜" aria-label="Permalink to &quot;傻瓜&quot;">​</a></h2><ul><li>2008-02-28 韩国 106分钟</li><li>类型：喜剧、爱情</li><li>导演：金正权</li><li>主演：车太贤、河智苑、朴熙顺</li><li>百科：该片改编自韩国网络漫画家姜道英的同名漫画《傻瓜》，讲述在一条小村子里有位27岁还天真烂漫的傻瓜承龙，一边照顾着唯一的妹妹，一边等待外留学的初恋，终于在10年等待后，这位承龙心目中的天使回到了小村庄，重新相遇后二人发生的故事</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005F69BBC914187C0798D79448" alt=""></p>',18),r=[o];function s(c,h,m,n,p,d){return l(),a("div",null,r)}const b=i(t,[["render",s]]);export{u as __pageData,b as default};
